const http  = require('http');
const https = require('https');
const fs    = require('fs');
const path  = require('path');
const zlib  = require('zlib');
const { execSync } = require('child_process');
const Terser   = require('terser');
const CleanCSS = require('clean-css');
// GLOBAL-PLACE-SEARCH-B2-TIMEZONE (2026-05-12): lat/lng → IANA tz.
// Used by /api/search-place external fallback so multi-tz countries
// (US/CA/RU/AU) get the CORRECT regional timezone, not just the
// country's primary. Synchronous, ~16KB, zero transitive deps. Falls
// through to `_CC_TO_PRIMARY_TZ` only if the lat/lng lookup errors.
let _tzLookup = null;
try { _tzLookup = require('tz-lookup'); } catch (_) { /* lib missing → use country fallback */ }
// MoonCalc للـ SSR: حقن أرقام حقيقيّة (إضاءة/عمر/طور) في فقرة /moon-today-in-{slug}
// TRANSLATIONS للـ SSR: لترجمة أسماء الأطوار والأبراج قبل الإرسال (بدون Googlebot-JS)
const MoonCalc   = require('./js/moon.js');
const { TRANSLATIONS: I18N } = require('./js/i18n.js');
// SSR-Prayer-Times: pre-compute the 5 daily prayer times on the server so the
//   FIRST byte of HTML carries real numbers (07:24, 12:15, …) instead of
//   "--:--" placeholders. Googlebot indexes the rendered numbers without
//   waiting for JS — same algorithm runs client-side to update for the
//   visitor's location after page load.
const PrayerTimesSrv = require('./js/prayer-times.js');

// 🆕 Round 2.1 (H): Build hash — git short SHA مُحسَب مرّة عند الإقلاع
// يُضاف لـ asset URLs كـ&b={hash} → يُبطّل الـcache عند كلّ deploy (بدون bump يدويّ)
// fallback إلى 'dev' عند غياب git أو .git/
const BUILD_HASH = (() => {
    try {
        return execSync('git rev-parse --short HEAD', { cwd: __dirname, stdio: ['ignore', 'pipe', 'ignore'] })
            .toString().trim() || 'dev';
    } catch (_e) { return 'dev'; }
})();

// ===== معالجات أخطاء العملية (تمنع السقوط الكلي عند خطأ واحد) =====
process.on('uncaughtException', (err) => {
    console.error('[FATAL uncaughtException]', err && err.stack || err);
});
process.on('unhandledRejection', (reason) => {
    console.error('[FATAL unhandledRejection]', reason && reason.stack || reason);
});

const PORT    = process.env.PORT || 8080;
const ROOT    = __dirname;
const DB_DIR  = path.join(ROOT, 'db');   // قاعدة البيانات الدائمة

// GLOBAL-PLACE-SEARCH-TEST-PAGE-A (2026-05-12): curated places dataset
// Loaded once at startup. Used by /api/search-place (the new isolated
// search engine that powers /search-test only — NOT the real homepage
// search box). Phase A scope: this dict is the ONLY source.
let _CURATED_PLACES = [];
try {
    const _p = path.join(DB_DIR, 'places', 'curated-places.json');
    if (fs.existsSync(_p)) {
        const _raw = fs.readFileSync(_p, 'utf8');
        const _arr = JSON.parse(_raw);
        if (Array.isArray(_arr)) _CURATED_PLACES = _arr.filter(_isPrayerTimesReady);
    }
} catch (_) { /* silent — empty dataset = empty results, not a crash */ }

// Every prayer-times page needs lat + lng + timezone to compute. Drop
// any curated entry that's missing the contract — never surface a
// click target that can't render.
function _isPrayerTimesReady(p) {
    if (!p || typeof p !== 'object') return false;
    if (typeof p.slug !== 'string' || !/^[a-z0-9][a-z0-9-]{0,79}$/.test(p.slug)) return false;
    if (typeof p.countryCode !== 'string' || !/^[a-z]{2}$/.test(p.countryCode)) return false;
    const lat = Number(p.lat), lng = Number(p.lng);
    if (!isFinite(lat) || lat < -90 || lat > 90) return false;
    if (!isFinite(lng) || lng < -180 || lng > 180) return false;
    if (typeof p.timezone !== 'string' || !p.timezone) return false;
    if (!p.names || typeof p.names !== 'object') return false;
    return true;
}

// Small Arabic+Latin normalization (mirrors the client `_normArabic` /
// `normalizeText` semantics enough to match the same way the client
// would). NFD-fold Latin diacritics, lowercase, Arabic alif/ta-marbuta
// folding, dashes/underscores → spaces.
function _normSearchText(s) {
    if (!s) return '';
    let out = String(s).toLowerCase();
    // Arabic folding
    out = out
        .replace(/[أإآٱا]/g, 'ا')  // أإآٱ ا → ا
        .replace(/ى/g, 'ي')  // ى → ي
        .replace(/ؤ/g, 'و')  // ؤ → و
        .replace(/ئ/g, 'ي')  // ئ → ي
        .replace(/ة/g, 'ه')  // ة → ه
        .replace(/[ً-ٰٟ]/g, '');  // diacritics
    // Latin diacritics
    out = out.normalize('NFD').replace(/[̀-ͯ]/g, '');
    // collapse separators
    out = out.replace(/[-_]+/g, ' ').replace(/\s+/g, ' ').trim();
    return out;
}

// GLOBAL-PLACE-SEARCH-LANG-1 (2026-05-12): the 10 UI languages this
// site supports. Every search result MUST be localizable to each one
// via either curated data or runtime resolution. `Intl.DisplayNames`
// generates accurate country names for all 10 (verified) so we don't
// have to hand-curate a 200-country × 10-lang static dict.
const _SUPPORTED_LANGS = ['ar','en','fr','de','tr','ur','id','es','bn','ms'];

// Cached `Intl.DisplayNames` instances per lang — avoid recreating on
// every request (Intl.DisplayNames construction is non-trivial).
const _COUNTRY_DN_CACHE = {};
function _getCountryName(cc, lang) {
    if (!cc || typeof cc !== 'string') return '';
    const upper = cc.toUpperCase();
    const code = String(lang || 'en').toLowerCase();
    const langKey = _SUPPORTED_LANGS.includes(code) ? code : 'en';
    try {
        if (!_COUNTRY_DN_CACHE[langKey]) {
            _COUNTRY_DN_CACHE[langKey] = new Intl.DisplayNames([langKey], { type: 'region' });
        }
        return _COUNTRY_DN_CACHE[langKey].of(upper) || '';
    } catch (_) { return ''; }
}

// ═══ GLOBAL-PLACE-SEARCH-L10N-PIPELINE (2026-05-12) ═══
// Approximate Latin → Arabic transliteration. Used as a fallback tier
// in `_pickLocalizedDisplayQ` when Nominatim has NO `name:ar` namedetail
// for a place and we'd otherwise leak Latin into the Arabic UI.
// NOT perfect transliteration — known limitations:
//   * vowels are dropped/duplicated approximately ("Pontet" → "بونتت")
//   * letter "c" is contextual (c+e/i → س, else → ك)
//   * proper Arabic morphology / ta-marbuta / hamza placement NOT applied
// The output is marked `quality: 'transliterated'` so downstream
// (Phase D admin review) can promote curated Arabic names later.
const _AR_TRANSLIT_BIGRAMS = {
    'ph': 'ف', 'sh': 'ش', 'ch': 'ش', 'th': 'ث', 'kh': 'خ',
    'gh': 'غ', 'dh': 'ذ', 'oo': 'و', 'ee': 'ي', 'ou': 'و',
    'eu': 'و', 'ai': 'اي', 'ei': 'اي', 'oi': 'وا', 'au': 'و',
    'ck': 'ك'
};
const _AR_TRANSLIT_LETTERS = {
    'a': 'ا', 'b': 'ب', 'd': 'د', 'e': '', 'f': 'ف', 'g': 'ج',
    'h': 'ه', 'i': 'ي', 'j': 'ج', 'k': 'ك', 'l': 'ل', 'm': 'م',
    'n': 'ن', 'o': 'و', 'p': 'ب', 'q': 'ق', 'r': 'ر', 's': 'س',
    't': 'ت', 'u': 'و', 'v': 'ف', 'w': 'و', 'x': 'كس', 'y': 'ي',
    'z': 'ز'
};
// Common French/Italian/Spanish word-particles to handle BEFORE
// char-by-char. Conservative — avoids accidental rewrites.
const _AR_TRANSLIT_PARTICLES = [
    [/\bsaint\s/g, 'سان '],   [/\bsainte\s/g, 'سانت '],
    [/\bsan\s/g, 'سان '],     [/\bsanta\s/g, 'سانتا '],
    [/\bsanto\s/g, 'سانتو '], [/\bsão\s/g, 'ساو '],
    [/\bles\s/g, 'لو '],       [/\ble\s/g, 'لو '],
    [/\bla\s/g, 'لا '],         [/\bvon\s/g, 'فون '],
    [/\bnew\s/g, 'نيو '],      [/\bvilla\s/g, 'فيلا '],
    [/\bville\s/g, 'فيل '],     [/\bsur\s/g, 'سور '],
    [/\bsous\s/g, 'سو '],       [/\bport\s/g, 'بور '],
    [/\bel\s/g, 'إل '],         [/\bal-/g, 'ال'],
    [/\bel-/g, 'ال'],            [/\bde\s/g, 'دو '],
    [/\bdu\s/g, 'دو '],          [/\bdes\s/g, 'دي '],
    [/\bda\s/g, 'دا '],           [/\bdi\s/g, 'دي '],
    [/\bdo\s/g, 'دو ']
];

function _transliterateLatinToArabic(s) {
    if (!s || typeof s !== 'string') return '';
    // Normalize: lowercase, strip diacritics, collapse separators
    let t = s.toLowerCase()
        .normalize('NFD').replace(/[̀-ͯ]/g, '')
        .replace(/[-'']/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    if (!t) return '';
    // Apply word particles first
    for (const [re, rep] of _AR_TRANSLIT_PARTICLES) t = t.replace(re, rep);
    // Char-by-char with bigram lookahead
    let out = '';
    let i = 0;
    while (i < t.length) {
        const ch = t[i];
        const nx = t[i + 1];
        // Already-Arabic char passes through
        if (/[؀-ۿ]/.test(ch)) { out += ch; i++; continue; }
        // Whitespace passes through
        if (/\s/.test(ch)) { out += ' '; i++; continue; }
        // Bigram lookup
        const bg = ch + (nx || '');
        if (_AR_TRANSLIT_BIGRAMS[bg]) { out += _AR_TRANSLIT_BIGRAMS[bg]; i += 2; continue; }
        // Contextual c: before e/i/y → س, else → ك
        if (ch === 'c') {
            if (nx === 'e' || nx === 'i' || nx === 'y') { out += 'س'; i++; }
            else { out += 'ك'; i++; }
            continue;
        }
        // Single letter
        if (_AR_TRANSLIT_LETTERS[ch] !== undefined) {
            out += _AR_TRANSLIT_LETTERS[ch]; i++; continue;
        }
        // Drop unknown (punctuation, digits, etc.)
        i++;
    }
    // Collapse multi-space + strip leading-space + remove leftover Latin
    return out.replace(/[a-z]/gi, '').replace(/\s+/g, ' ').trim();
}

// Pick the best `displayName` for a place + UI lang, applying the full
// per-spec L10N-PIPELINE. Returns `{ value, quality }` where quality
// is one of:
//   'curated'        — names[lang] from curated/discovered store
//   'official'       — namedetails name:lang from Nominatim
//   'alias'          — aliases[lang][0] from curated
//   'alias_lang'     — AR-only: an Arabic-script name from another lang slot
//   'transliterated' — AR-only: approximate Latin→Arabic transliteration
//   'fallback_en'    — names.en
//   'fallback_raw'   — raw OSM name (Latin)
//   'empty'          — nothing produced
//
// AR is the only lang that gets the alias_lang + transliterated tiers,
// because Latin inside Arabic UI looks bad. Other Latin-script langs
// (en/fr/de/es/id/ms/tr/vi) just fall through to fallback_en/raw.
function _pickLocalizedDisplayQ(place, lang, namedetailsByLang, fallbackRawName) {
    const code = String(lang || 'ar').toLowerCase();
    const names = (place && place.names) || {};
    const aliases = (place && place.aliases) || {};
    const nd = namedetailsByLang || {};

    // 1. curated/discovered names[lang]
    if (typeof names[code] === 'string' && names[code].trim()) {
        return { value: names[code].trim(), quality: 'curated' };
    }
    // 2. external namedetails name:lang
    if (typeof nd[code] === 'string' && nd[code].trim()) {
        return { value: nd[code].trim(), quality: 'official' };
    }
    // 3. first alias in this lang
    if (Array.isArray(aliases[code]) && aliases[code].length > 0
        && typeof aliases[code][0] === 'string' && aliases[code][0].trim()) {
        return { value: aliases[code][0].trim(), quality: 'alias' };
    }
    // 4. AR-only — refuse Latin if any Arabic-script alternative exists
    //    Scans BOTH curated names AND Nominatim namedetails.
    if (code === 'ar') {
        for (const k of _SUPPORTED_LANGS) {
            const v = names[k];
            if (typeof v === 'string' && /[؀-ۿ]/.test(v)) {
                return { value: v.trim(), quality: 'alias_lang' };
            }
            const vd = nd[k];
            if (typeof vd === 'string' && /[؀-ۿ]/.test(vd)) {
                return { value: vd.trim(), quality: 'alias_lang' };
            }
        }
        if (fallbackRawName && /[؀-ۿ]/.test(String(fallbackRawName))) {
            return { value: String(fallbackRawName).trim(), quality: 'alias_lang' };
        }
        // 5. AR-only transliteration from the best Latin source available
        const latinSrc = (typeof names.en === 'string' && names.en.trim())
            ? names.en.trim()
            : (typeof nd.en === 'string' && nd.en.trim())
                ? nd.en.trim()
                : (fallbackRawName ? String(fallbackRawName).trim() : '');
        if (latinSrc) {
            const translit = _transliterateLatinToArabic(latinSrc);
            // Only accept if it produced a non-trivial Arabic string
            if (translit && /[؀-ۿ]/.test(translit) && translit.length >= 2) {
                return { value: translit, quality: 'transliterated' };
            }
        }
    }
    // 6. English fallback
    if (typeof names.en === 'string' && names.en.trim()) {
        return { value: names.en.trim(), quality: 'fallback_en' };
    }
    if (typeof nd.en === 'string' && nd.en.trim()) {
        return { value: nd.en.trim(), quality: 'fallback_en' };
    }
    // 7. Raw OSM name — last resort. May leak Latin even for AR.
    if (fallbackRawName) {
        return { value: String(fallbackRawName).trim(), quality: 'fallback_raw' };
    }
    return { value: '', quality: 'empty' };
}

// Back-compat shim — returns just the string. New code should call
// `_pickLocalizedDisplayQ` to also get the `quality` tag.
function _pickLocalizedDisplay(place, lang, namedetailsByLang, fallbackRawName) {
    return _pickLocalizedDisplayQ(place, lang, namedetailsByLang, fallbackRawName).value;
}

// Build a `names` object from a Nominatim result for all 10 langs that
// have a `namedetails[name:{lang}]` tag. Missing langs stay undefined
// so callers know to fall back. (External enrichment for missing langs
// is deferred to Phase D — Wikidata/GeoNames sync.)
function _extractNamedetailsByLang(nd) {
    const out = {};
    if (!nd || typeof nd !== 'object') return out;
    for (const lang of _SUPPORTED_LANGS) {
        const k = 'name:' + lang;
        if (typeof nd[k] === 'string' && nd[k].trim()) out[lang] = nd[k].trim();
    }
    return out;
}

// Phase-A search. Pure local lookup against `_CURATED_PLACES`. Returns
// at most 10 results in the unified contract shape, validated.
function _searchCuratedPlaces(query, lang) {
    if (!query || typeof query !== 'string') return [];
    const qNorm = _normSearchText(query);
    if (!qNorm) return [];
    const qCompact = qNorm.replace(/\s+/g, '');
    if (qCompact.length < 1) return [];
    const scored = [];
    for (const p of _CURATED_PLACES) {
        if (!_isPrayerTimesReady(p)) continue;
        // Gather candidate strings across all langs + aliases + slug + country
        const candidates = [];
        try {
            if (p.names && typeof p.names === 'object') {
                for (const k of Object.keys(p.names)) {
                    if (typeof p.names[k] === 'string') candidates.push(p.names[k]);
                }
            }
            if (p.aliases && typeof p.aliases === 'object') {
                for (const k of Object.keys(p.aliases)) {
                    const arr = p.aliases[k];
                    if (Array.isArray(arr)) for (const v of arr) if (typeof v === 'string') candidates.push(v);
                }
            }
            if (typeof p.slug === 'string') candidates.push(p.slug.replace(/-/g, ' '));
            if (p.admin) {
                if (typeof p.admin.countryAr === 'string') candidates.push(p.admin.countryAr);
                if (typeof p.admin.countryEn === 'string') candidates.push(p.admin.countryEn);
            }
        } catch (_) {}
        const normalized = candidates.map(_normSearchText).filter(Boolean);
        const normCompact = normalized.map(s => s.replace(/\s+/g, ''));
        // Match-tier scoring
        let score = 0;
        if (normalized.some(s => s === qNorm))                                   score = 100;
        else if (normCompact.some(s => s === qCompact))                          score = 95;
        else if (normalized.some(s => s.startsWith(qNorm)))                      score = 80;
        else if (normCompact.some(s => s.startsWith(qCompact)))                  score = 75;
        else if (normalized.some(s => (' ' + s).includes(' ' + qNorm)))          score = 60;
        else if (normalized.some(s => s.includes(qNorm)))                        score = 40;
        else if (normCompact.some(s => s.includes(qCompact)))                    score = 38;
        if (score === 0) continue;
        // Weight by priority
        const prio = Number.isFinite(p.priority) ? p.priority : 50;
        const finalScore = score + prio * 0.3;
        // Build the result in the unified contract shape.
        // LANG-1: use the per-spec fallback chain for displayName and
        // Intl.DisplayNames for countryName so all 10 langs work.
        // L10N-PIPELINE: surface nameQuality so the API exposes how
        // the name was resolved (curated > namedetails > transliteration).
        const code = String(lang || 'ar').toLowerCase();
        const picked = _pickLocalizedDisplayQ(p, code, null, p.slug);
        const displayName = picked.value;
        const nameQuality = picked.quality;
        // Prefer admin.country.{lang} from curated data if explicitly
        // provided (covers special cases like "المملكة العربية السعودية"
        // vs Intl's shorter "السعودية"); otherwise use Intl runtime.
        let countryName = '';
        if (p.admin && p.admin.country && typeof p.admin.country === 'object'
            && typeof p.admin.country[code] === 'string') {
            countryName = p.admin.country[code];
        } else if (p.admin && code === 'ar' && typeof p.admin.countryAr === 'string') {
            countryName = p.admin.countryAr;  // back-compat for old shape
        } else if (p.admin && code === 'en' && typeof p.admin.countryEn === 'string') {
            countryName = p.admin.countryEn;
        }
        if (!countryName) countryName = _getCountryName(p.countryCode, code);
        scored.push({
            slug: p.slug,
            type: p.type || 'city',
            displayName,
            secondaryName: (p.names && p.names.en) || p.slug,
            countryName,
            countryCode: p.countryCode,
            lat: p.lat,
            lng: p.lng,
            timezone: p.timezone,
            source: p.source || 'curated',
            confidence: Math.round(finalScore),
            nameQuality,
            _sort: finalScore
        });
    }
    scored.sort((a, b) => b._sort - a._sort);
    return scored.slice(0, 10).map(({ _sort, ...rest }) => rest);
}

// ═══ GLOBAL-PLACE-SEARCH-TEST-PAGE-B (2026-05-12): external fallback ═══
// When `_searchCuratedPlaces` returns 0 results, fall back to Nominatim
// FROM THE SERVER (the browser never sees external calls). Hits go
// through a 1-hour in-memory cache to avoid repeat queries. Strict
// filter: only accept place types that can host a prayer-times page
// (city / town / village / governorate / state_district / etc.) — no
// roads / shops / hotels / amenities. Every result is hardened against
// the prayer-times contract (slug + lat + lng + timezone + country
// code + names dict) before being returned.
//
// Scope (Phase B): consumed ONLY by /api/search-place which serves
// the /search-test page. The real homepage search box stays on its
// current pipeline (fetchCitySuggestions in js/app.js).

const _EXTERNAL_ALLOWED_TYPES = new Set([
    'city', 'town', 'village', 'hamlet', 'locality', 'municipality',
    'suburb', 'subdistrict', 'district', 'county', 'state_district',
    'province', 'state', 'region', 'governorate', 'administrative'
]);
const _EXTERNAL_BLOCKED_TYPES = new Set([
    'road', 'street', 'highway', 'building', 'shop', 'hotel',
    'restaurant', 'tourism', 'amenity', 'commercial', 'office',
    'house', 'postcode', 'fuel', 'pharmacy', 'neighbourhood',
    'quarter', 'residential', 'cafe', 'bar', 'pub', 'bank', 'mall',
    'aeroway', 'railway', 'waterway', 'landuse', 'natural', 'peak',
    'mountain', 'park', 'forest', 'beach', 'island', 'isolated_dwelling',
    'farm', 'plot', 'country'
]);

// Acceptance test for a raw Nominatim result. Must pass to surface.
function _isAcceptableExternalPlace(p) {
    if (!p || typeof p !== 'object') return false;
    const addr = String(p.addresstype || '').toLowerCase();
    const type = String(p.type || '').toLowerCase();
    const cls  = String(p.class || '').toLowerCase();
    // Reject explicitly blocked types in any field
    if (_EXTERNAL_BLOCKED_TYPES.has(addr)) return false;
    if (_EXTERNAL_BLOCKED_TYPES.has(type)) return false;
    if (_EXTERNAL_BLOCKED_TYPES.has(cls))  return false;
    // Allow by addresstype (Nominatim's most-reliable place classifier)
    if (_EXTERNAL_ALLOWED_TYPES.has(addr)) return true;
    // boundary + administrative is a valid place (governorate / district)
    if (cls === 'boundary' && type === 'administrative') return true;
    // place class with an allowed sub-type
    if (cls === 'place' && _EXTERNAL_ALLOWED_TYPES.has(type)) return true;
    return false;
}

// Resolve a unified "type" string from a Nominatim result.
function _resolveExternalType(p) {
    const addr = String(p.addresstype || '').toLowerCase();
    if (_EXTERNAL_ALLOWED_TYPES.has(addr)) return addr;
    const type = String(p.type || '').toLowerCase();
    if (_EXTERNAL_ALLOWED_TYPES.has(type)) return type;
    return 'city';  // fallback for boundary/administrative
}

// Slugify: NFD-fold diacritics, lowercase, alphanumeric-only with
// hyphens. Same shape as our curated slugs so they're interchangeable.
function _slugifyPlace(name) {
    if (!name) return '';
    return String(name)
        .normalize('NFD').replace(/[̀-ͯ]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .slice(0, 80);
}

// Build a UNIQUE slug. If the base collides with another result in the
// same batch OR with a curated place, append the country code (and a
// numeric suffix if still colliding).
function _generateUniqueSlug(englishName, countryCode, taken) {
    let base = _slugifyPlace(englishName);
    if (!base) return null;
    if (!/^[a-z0-9][a-z0-9-]{0,79}$/.test(base)) return null;
    if (!taken.has(base)) { taken.add(base); return base; }
    const withCc = (base + '-' + (countryCode || 'xx')).slice(0, 80);
    if (!taken.has(withCc) && /^[a-z0-9][a-z0-9-]{0,79}$/.test(withCc)) {
        taken.add(withCc);
        return withCc;
    }
    // Last resort: numeric suffix
    for (let i = 2; i <= 9; i++) {
        const v = (base + '-' + i).slice(0, 80);
        if (!taken.has(v)) { taken.add(v); return v; }
    }
    return null;
}

// Map a Nominatim result to the prayer-times-ready contract. Returns
// null if any required field can't be derived.
function _normalizeExternalPlace(p, lang, takenSlugs) {
    if (!_isAcceptableExternalPlace(p)) return null;
    const addr = p.address || {};
    const nd   = p.namedetails || {};
    const code = String(lang || 'ar').toLowerCase();

    // Coordinates — required.
    const lat = Number(p.lat);
    const lng = Number(p.lon != null ? p.lon : p.lng);
    if (!isFinite(lat) || lat < -90 || lat > 90)  return null;
    if (!isFinite(lng) || lng < -180 || lng > 180) return null;

    // Country code — required, must be 2-letter ISO.
    const cc = String(addr.country_code || '').toLowerCase();
    if (!/^[a-z]{2}$/.test(cc)) return null;

    // Timezone — required. PHASE B2 (2026-05-12): derive from lat/lng
    // via `tz-lookup` first so multi-timezone countries (US/CA/RU/AU)
    // resolve to the CORRECT regional zone (Montreal → America/Toronto
    // ≠ Vancouver → America/Vancouver). Fall back to country-code map
    // only if the lib is unavailable or throws (extreme lat/lng,
    // unmapped ocean, etc.). Drop the result if BOTH paths fail —
    // we never surface a city that can't compute prayer times.
    let tz = null;
    if (_tzLookup) {
        try { tz = _tzLookup(lat, lng) || null; } catch (_) { tz = null; }
    }
    if (!tz) tz = _CC_TO_PRIMARY_TZ[cc] || null;
    if (!tz) return null;

    // English / canonical name — required to build a slug.
    const _stripAdminSuffix = (s) => String(s || '')
        .replace(/^(محافظة|منطقة|مقاطعة|ولاية|إمارة)\s+/i, '')
        .replace(/\s+(Governorate|Province|Region|District|County|State|Emirate|Municipality)$/i, '')
        .trim();
    const enRaw = (nd['name:en'] || addr.city || addr.town || addr.village ||
                   addr.municipality || p.name || '').trim();
    const enName = _stripAdminSuffix(enRaw);
    if (!enName) return null;

    // Slug — required, unique within this batch.
    const slug = _generateUniqueSlug(enName, cc, takenSlugs);
    if (!slug) return null;

    // LANG-1 (2026-05-12): build a full `names` map across all 10
    // supported langs from Nominatim's `namedetails` (when available).
    // L10N-PIPELINE (2026-05-12): we DO NOT seed namedetailsByLang[code]
    // from addr.* anymore — addr.* always comes back English now (we
    // cache the raw at accept-language=en), so seeding it for AR would
    // leak Latin and mis-flag it as quality:'official'. Missing langs
    // stay undefined; the Q-picker's transliteration tier handles AR.
    const namedetailsByLang = _extractNamedetailsByLang(nd);
    // Strip admin suffixes from every entry
    for (const k of Object.keys(namedetailsByLang)) {
        namedetailsByLang[k] = _stripAdminSuffix(namedetailsByLang[k]);
    }

    // Final displayName via the spec-compliant fallback chain.
    // L10N-PIPELINE: pass namedetailsByLang via the 3rd param (`nd`),
    // NOT bundled into `place.names`, so step 2 ('official') wins
    // instead of step 1 ('curated') being mis-tagged. The Q-picker's
    // transliteration tier uses `nd.en` (if available) or `fallbackRawName`
    // as the Latin source for AR transliteration.
    const synthPlace = { names: {}, aliases: {} };
    const picked = _pickLocalizedDisplayQ(
        synthPlace, code, namedetailsByLang, _stripAdminSuffix(p.name || enName)
    );
    let displayName = picked.value;
    let nameQuality = picked.quality;
    if (!displayName) { displayName = enName; nameQuality = 'fallback_en'; }

    // Country name: prefer Intl.DisplayNames localized to the REQUEST
    // language (runtime, no Nominatim round-trip needed). Fall back to
    // whatever Nominatim returned (English, since we cached with
    // accept-language=en) if Intl can't resolve the code.
    // LANG-1 (2026-05-12): we localize per request, NOT from the cached
    // English `addr.country`, so 10 lang variants of the same query
    // surface 10 properly-translated country names.
    let countryName = _getCountryName(cc, code);
    if (!countryName) countryName = String(addr.country || '').trim();
    if (!countryName) return null;

    // Importance from Nominatim ranges 0..1 — scale to 0..100.
    const imp = Number(p.importance);
    const confidence = isFinite(imp) ? Math.max(0, Math.min(100, Math.round(imp * 100))) : 50;

    return {
        slug,
        type: _resolveExternalType(p),
        displayName,
        secondaryName: enName,
        countryName,
        countryCode: cc,
        lat, lng,
        timezone: tz,
        source: 'nominatim',
        confidence,
        // LANG-1: full per-lang names map. Useful for Phase-C
        // persistence (we'll store this in discovered_places so future
        // searches in OTHER langs find the city without re-querying
        // Nominatim).
        names: namedetailsByLang,
        // L10N-PIPELINE: how `displayName` was produced. Persisted
        // in `discovered_places.name_quality` so Phase D admin review
        // can promote 'transliterated' → 'official' over time.
        nameQuality
    };
}

// In-memory cache. 1-hour TTL. Keyed by `${lang}:${normalizedQuery}`.
// Phase-C will replace this with an external store (Redis / Postgres).
const _externalSearchCache = new Map();
const _EXTERNAL_CACHE_TTL = 60 * 60 * 1000;
const _EXTERNAL_CACHE_MAX = 1000;

async function _searchExternalPlaces(query, lang) {
    const q = String(query || '').trim();
    if (q.length < 2 || q.length > 80) return [];
    const langCode = _SUPPORTED_LANGS.includes(lang) ? lang : 'ar';
    // LANG-1 (2026-05-12): cache is lang-AGNOSTIC. We hit Nominatim with
    // accept-language=en for a canonical raw response, and re-localize
    // per request from namedetails. Cuts external calls by 10× when the
    // same query comes in across multiple langs (e.g. test suite).
    const cacheKey = q.toLowerCase();
    const cached = _externalSearchCache.get(cacheKey);
    let raw;
    if (cached && Date.now() - cached.ts < _EXTERNAL_CACHE_TTL) {
        raw = cached.raw;
    } else {
        raw = [];
        try {
            const url = 'https://nominatim.openstreetmap.org/search'
                + '?format=jsonv2'
                + '&addressdetails=1'
                + '&namedetails=1'
                + '&limit=10'
                + '&accept-language=en'  // canonical; namedetails carries every lang
                + '&q=' + encodeURIComponent(q);
            const ctrl = new AbortController();
            const timer = setTimeout(() => ctrl.abort(), 8000);
            const resp = await fetch(url, {
                signal: ctrl.signal,
                headers: {
                    'User-Agent': 'PrayerTimesApp/1.0 (+https://prayer-times-d4w8.onrender.com)',
                    'Accept': 'application/json'
                }
            });
            clearTimeout(timer);
            if (resp.ok) {
                const data = await resp.json();
                if (Array.isArray(data)) raw = data;
            }
        } catch (_e) { /* network/timeout/abort → empty raw */ }
        // Cache the RAW response (lang-agnostic) so the next localized
        // call to the same query doesn't re-hit Nominatim.
        _externalSearchCache.set(cacheKey, { ts: Date.now(), raw });
        if (_externalSearchCache.size > _EXTERNAL_CACHE_MAX) {
            const firstKey = _externalSearchCache.keys().next().value;
            _externalSearchCache.delete(firstKey);
        }
    }
    // Localize the cached raw results per the requested lang. This is
    // pure CPU work (no network).
    const taken = new Set();
    for (const p of _CURATED_PLACES) {
        if (p && typeof p.slug === 'string') taken.add(p.slug);
    }
    const results = [];
    for (const p of (raw || [])) {
        const norm = _normalizeExternalPlace(p, langCode, taken);
        if (norm) results.push(norm);
    }
    // Sort by type-rank then confidence
    const typeRank = (t) => {
        const m = {
            city: 0, town: 1, municipality: 2, borough: 2,
            governorate: 3, province: 3, state: 3, state_district: 3,
            county: 4, district: 4, subdistrict: 4, suburb: 4, administrative: 5,
            village: 6, hamlet: 7, locality: 8, region: 9
        };
        return m[t] != null ? m[t] : 10;
    };
    results.sort((a, b) => {
        const r = typeRank(a.type) - typeRank(b.type);
        if (r !== 0) return r;
        return (b.confidence || 0) - (a.confidence || 0);
    });
    return results.slice(0, 10);
}

// ═══ GLOBAL-PLACE-SEARCH-PHASE-C (2026-05-12): Supabase/Postgres ═════════════
// discovered_places: places persisted ONLY after a user explicitly picks an
// external (Nominatim) result in /search-test. The persisted record carries
// the full 10-language `names` map (LANG-1 contract) so future searches in
// any UI lang find the city locally without re-querying Nominatim. The
// table is gated behind SUPABASE_URL + SUPABASE_SERVICE_ROLE_KEY env vars;
// when either is missing the server logs a one-line warning at startup and
// falls back to curated + external only (the site keeps working).
//
// We call Supabase's PostgREST API directly via `fetch` — no extra npm
// dependency. Service-role key bypasses RLS (it's server-only, never in JS).
const _SUPABASE_URL = String(process.env.SUPABASE_URL || '').replace(/\/+$/, '');
const _SUPABASE_KEY = String(process.env.SUPABASE_SERVICE_ROLE_KEY || '');
const _SUPABASE_ENABLED = !!(_SUPABASE_URL && _SUPABASE_KEY);

if (!_SUPABASE_ENABLED) {
    try {
        console.warn('[discovered_places] SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY missing — Phase-C discovered layer DISABLED. /api/search-place will use curated + external only.');
    } catch (_) {}
}

async function _supabaseFetch(pathAndQuery, opts) {
    if (!_SUPABASE_ENABLED) return null;
    const url = _SUPABASE_URL + pathAndQuery;
    const headers = Object.assign({
        'apikey': _SUPABASE_KEY,
        'Authorization': 'Bearer ' + _SUPABASE_KEY,
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }, (opts && opts.headers) || {});
    try {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 5000);
        const r = await fetch(url, Object.assign({}, opts, { headers, signal: ctrl.signal }));
        clearTimeout(timer);
        if (!r.ok) return null;
        // Some PATCH/POST with Prefer: return=minimal returns 201/204 + empty body
        const ct = String(r.headers.get('content-type') || '');
        if (!ct.includes('json')) return [];
        return await r.json();
    } catch (_) { return null; }
}

// Map a Postgres row → unified /api/search-place result shape. Reuses
// the same `_pickLocalizedDisplay` + `_getCountryName` helpers as curated
// and external, so the response shape is identical regardless of source.
function _mapDiscoveredRow(row, lang) {
    if (!row || !row.slug) return null;
    if (!isFinite(row.lat) || !isFinite(row.lng)) return null;
    if (!row.timezone || !row.country_code) return null;
    const code = String(lang || 'ar').toLowerCase();
    const synthPlace = {
        names:   row.names   || {},
        aliases: row.aliases || {},
        admin:   row.admin   || {}
    };
    // L10N-PIPELINE: discovered rows go through the same full pipeline.
    // Pre-stored name_quality (Phase D) will override this; for now we
    // recompute on read.
    const picked = _pickLocalizedDisplayQ(synthPlace, code, null, row.slug);
    const displayName = picked.value;
    const nameQuality = picked.quality;
    if (!displayName) return null;
    let countryName = '';
    if (row.admin && row.admin.country && typeof row.admin.country === 'object'
        && typeof row.admin.country[code] === 'string') {
        countryName = row.admin.country[code];
    }
    if (!countryName) countryName = _getCountryName(row.country_code, code);
    if (!countryName) return null;
    return {
        slug: row.slug,
        type: row.type || 'city',
        displayName,
        secondaryName: (synthPlace.names.en || row.slug),
        countryName,
        countryCode: row.country_code,
        lat: row.lat,
        lng: row.lng,
        timezone: row.timezone,
        source: 'discovered',
        // Slightly higher confidence than fresh external (it's been picked
        // by at least one user → real prayer-times destination).
        confidence: 70 + Math.min(20, Number(row.selected_count) || 0),
        // L10N-PIPELINE: live-computed quality from the stored names map.
        nameQuality
    };
}

async function _searchDiscoveredPlaces(query, lang) {
    if (!_SUPABASE_ENABLED) return [];
    const q = String(query || '').trim();
    if (q.length < 1 || q.length > 80) return [];
    // Call the search_discovered_places RPC. Returns rows ranked by
    // selected_count desc, search_count desc, last_used_at desc.
    const data = await _supabaseFetch('/rest/v1/rpc/search_discovered_places', {
        method: 'POST',
        body: JSON.stringify({ q, lim: 10 })
    });
    if (!Array.isArray(data)) return [];
    const mapped = data.map(row => _mapDiscoveredRow(row, lang)).filter(Boolean);
    // Fire-and-forget search_count increment (doesn't block the response).
    // We bump search_count for the TOP match if any, so popular cities
    // organically rise. Phase-D will use this for promotion candidates.
    if (mapped.length > 0 && data[0] && data[0].id) {
        const id = data[0].id;
        _supabaseFetch(
            '/rest/v1/discovered_places?id=eq.' + encodeURIComponent(id),
            {
                method: 'PATCH',
                headers: { 'Prefer': 'return=minimal' },
                body: JSON.stringify({ search_count: (data[0].search_count || 0) + 1 })
            }
        ).catch(() => {});
    }
    return mapped;
}

// Validator for incoming /api/place-selected payload. Independent of
// Supabase (test-friendly). Mirrors the prayer-times contract: every
// field needed to actually compute prayer times.
function _isValidDiscoveredInput(p) {
    if (!p || typeof p !== 'object') return false;
    if (typeof p.slug !== 'string' || !/^[a-z0-9][a-z0-9-]{0,79}$/.test(p.slug)) return false;
    const cc = String(p.countryCode || '').toLowerCase();
    if (!/^[a-z]{2}$/.test(cc)) return false;
    const lat = Number(p.lat), lng = Number(p.lng);
    if (!isFinite(lat) || lat < -90 || lat > 90) return false;
    if (!isFinite(lng) || lng < -180 || lng > 180) return false;
    if (typeof p.timezone !== 'string' || !p.timezone) return false;
    if (typeof p.type !== 'string' || !p.type) return false;
    // REJECT POI types — never persist a shop / road / etc.
    if (_EXTERNAL_BLOCKED_TYPES && _EXTERNAL_BLOCKED_TYPES.has(p.type)) return false;
    if (!p.names || typeof p.names !== 'object') return false;
    // At least one language name must be non-empty
    const hasName = Object.values(p.names).some(v => typeof v === 'string' && v.trim());
    if (!hasName) return false;
    // L10N-PIPELINE: nameQuality is optional. If present, it MUST be an
    // object whose values are recognised tier strings. Reject otherwise
    // so we never persist garbage in the name_quality jsonb column.
    if (p.nameQuality !== undefined && p.nameQuality !== null) {
        if (typeof p.nameQuality !== 'object' || Array.isArray(p.nameQuality)) return false;
        for (const v of Object.values(p.nameQuality)) {
            if (typeof v !== 'string') return false;
            if (!(v in _NAME_QUALITY_RANK)) return false;
        }
    }
    return true;
}

// Upsert a discovered place. Returns { action: 'inserted'|'updated'|'rejected', row }.
// Dedup strategy: (slug, country_code) unique → existing row gets
// selected_count++ + names/aliases merged with new data. Race-safe via
// the unique index — concurrent inserts of the same (slug, cc) cause
// ONE to win, the other gets a 23505 conflict which we treat as "found".
async function _upsertDiscoveredPlace(place) {
    if (!_SUPABASE_ENABLED) return { action: 'rejected', reason: 'supabase_disabled' };
    if (!_isValidDiscoveredInput(place)) return { action: 'rejected', reason: 'invalid' };
    const cc = String(place.countryCode).toLowerCase();
    // 1. Look up by (slug, country_code)
    const existing = await _supabaseFetch(
        '/rest/v1/discovered_places?select=*'
        + '&slug=eq.'         + encodeURIComponent(place.slug)
        + '&country_code=eq.' + encodeURIComponent(cc)
        + '&limit=1',
        { method: 'GET' }
    );
    if (Array.isArray(existing) && existing.length > 0) {
        const row = existing[0];
        // Merge names + aliases (don't drop existing langs)
        const mergedNames    = Object.assign({}, row.names   || {}, place.names   || {});
        const mergedAliases  = _mergeAliases(row.aliases || {}, place.aliases || {});
        const mergedAdmin    = Object.assign({}, row.admin || {}, place.admin   || {});
        // L10N-PIPELINE: name_quality — prefer existing 'curated'/'official'/'reviewed'
        // over incoming 'transliterated'/'fallback_*'. Only overwrite if incoming
        // tier is BETTER. Phase D admin review writes 'reviewed' which is sticky.
        const mergedQuality  = _mergeNameQuality(row.name_quality || {}, place.nameQuality || {});
        const patched = await _supabaseFetch(
            '/rest/v1/discovered_places?id=eq.' + encodeURIComponent(row.id),
            {
                method: 'PATCH',
                headers: { 'Prefer': 'return=representation' },
                body: JSON.stringify({
                    names:           mergedNames,
                    aliases:         mergedAliases,
                    admin:           mergedAdmin,
                    name_quality:    mergedQuality,
                    selected_count:  (row.selected_count || 0) + 1,
                    last_used_at:    new Date().toISOString()
                })
            }
        );
        return { action: 'updated', row: Array.isArray(patched) ? patched[0] : row };
    }
    // 2. Insert new row
    const inserted = await _supabaseFetch(
        '/rest/v1/discovered_places',
        {
            method: 'POST',
            headers: { 'Prefer': 'return=representation' },
            body: JSON.stringify({
                slug:           place.slug,
                type:           place.type,
                country_code:   cc,
                lat:            place.lat,
                lng:            place.lng,
                timezone:       place.timezone,
                names:          place.names       || {},
                aliases:        place.aliases     || {},
                admin:          place.admin       || {},
                name_quality:   place.nameQuality || {},
                source:         place.source      || 'nominatim',
                source_id:      place.sourceId    || null,
                verified:       false,
                selected_count: 1,
                last_used_at:   new Date().toISOString()
            })
        }
    );
    return { action: 'inserted', row: Array.isArray(inserted) ? inserted[0] : null };
}

// L10N-PIPELINE: rank table for name_quality merging. Higher = better.
// Phase D admin review will write 'reviewed' which is sticky (highest).
const _NAME_QUALITY_RANK = {
    'reviewed':      100,
    'curated':        90,
    'official':       80,
    'alias':          60,
    'alias_lang':     55,
    'fallback_en':    30,
    'transliterated': 20,
    'fallback_raw':   10,
    'empty':           0
};
function _mergeNameQuality(existing, incoming) {
    const out = Object.assign({}, existing || {});
    for (const lang of _SUPPORTED_LANGS) {
        const ex = (existing && typeof existing[lang] === 'string') ? existing[lang] : null;
        const inc = (incoming && typeof incoming[lang] === 'string') ? incoming[lang] : null;
        if (!inc) continue;
        if (!ex) { out[lang] = inc; continue; }
        const exRank = _NAME_QUALITY_RANK[ex] || 0;
        const incRank = _NAME_QUALITY_RANK[inc] || 0;
        if (incRank > exRank) out[lang] = inc;
    }
    return out;
}

// Merge two per-lang alias maps so we don't drop entries from either side.
function _mergeAliases(a, b) {
    const out = {};
    const keys = new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
    for (const k of keys) {
        const fromA = Array.isArray(a[k]) ? a[k] : [];
        const fromB = Array.isArray(b[k]) ? b[k] : [];
        const seen = new Set();
        const merged = [];
        for (const v of [...fromA, ...fromB]) {
            const s = String(v || '').trim();
            if (s && !seen.has(s)) { seen.add(s); merged.push(s); }
        }
        if (merged.length > 0) out[k] = merged;
    }
    return out;
}

// ===== المصدر الموحد للدومين =====
// في الإنتاج: SITE_URL=https://example.com node server.js
// محلياً: يُستخدم http://localhost:PORT تلقائياً
const SITE_URL = (process.env.SITE_URL || `http://localhost:${PORT}`).replace(/\/+$/, '');
function getBaseUrl() { return SITE_URL; }

// ===== خريطة أسماء الدول بالإنجليزية (لتوليد slugs للـ sitemap) =====
const COUNTRY_NAMES_EN = {
    sa:'Saudi Arabia', sy:'Syria', eg:'Egypt', iq:'Iraq',
    jo:'Jordan', lb:'Lebanon', ps:'Palestine', kw:'Kuwait', ae:'United Arab Emirates',
    qa:'Qatar', bh:'Bahrain', om:'Oman', ye:'Yemen', ly:'Libya',
    tn:'Tunisia', dz:'Algeria', ma:'Morocco', sd:'Sudan',
    dj:'Djibouti', km:'Comoros',
    pk:'Pakistan', tr:'Turkey', ir:'Iran', id:'Indonesia', my:'Malaysia',
    bd:'Bangladesh', af:'Afghanistan', in:'India', lk:'Sri Lanka', np:'Nepal',
    cn:'China', jp:'Japan', kr:'South Korea', kp:'North Korea', mn:'Mongolia',
    fr:'France', de:'Germany', gb:'United Kingdom', es:'Spain', it:'Italy',
    nl:'Netherlands', be:'Belgium', pt:'Portugal', se:'Sweden', no:'Norway',
    dk:'Denmark', fi:'Finland', pl:'Poland', ru:'Russia', ua:'Ukraine',
    ch:'Switzerland', at:'Austria', gr:'Greece', cz:'Czech Republic', ro:'Romania',
    us:'United States', ca:'Canada', mx:'Mexico',
    gt:'Guatemala', cu:'Cuba', do:'Dominican Republic',
    br:'Brazil', ar:'Argentina', co:'Colombia', pe:'Peru', ve:'Venezuela',
    cl:'Chile', ec:'Ecuador', bo:'Bolivia', py:'Paraguay', uy:'Uruguay',
    ng:'Nigeria', et:'Ethiopia', ke:'Kenya', tz:'Tanzania', za:'South Africa',
    gh:'Ghana', sn:'Senegal', cm:'Cameroon', ml:'Mali', so:'Somalia',
    ug:'Uganda', mr:'Mauritania', td:'Chad', ne:'Niger',
    au:'Australia', nz:'New Zealand',
    th:'Thailand', ph:'Philippines', vn:'Vietnam', mm:'Myanmar',
    kh:'Cambodia', la:'Laos', sg:'Singapore', bn:'Brunei', tl:'Timor-Leste',
    uz:'Uzbekistan', kz:'Kazakhstan', kg:'Kyrgyzstan', tj:'Tajikistan',
    tm:'Turkmenistan', az:'Azerbaijan', ge:'Georgia', am:'Armenia',
    xk:'Kosovo',
    // Round 7k — توسّع: 40 دولة إضافية (105 → 145)
    ba:'Bosnia and Herzegovina', al:'Albania', mk:'North Macedonia',
    bf:'Burkina Faso', ci:"Côte d'Ivoire", gn:'Guinea', gm:'Gambia',
    sl:'Sierra Leone', mv:'Maldives', er:'Eritrea', ss:'South Sudan',
    tg:'Togo', bj:'Benin',
    ie:'Ireland', hu:'Hungary', hr:'Croatia', rs:'Serbia',
    bg:'Bulgaria', si:'Slovenia', sk:'Slovakia',
    mg:'Madagascar', mz:'Mozambique', ao:'Angola', cd:'DR Congo',
    rw:'Rwanda', zw:'Zimbabwe', zm:'Zambia', mu:'Mauritius',
    lr:'Liberia', mw:'Malawi',
    sr:'Suriname', gy:'Guyana', tt:'Trinidad and Tobago', jm:'Jamaica',
    pa:'Panama', ht:'Haiti', cr:'Costa Rica',
    bt:'Bhutan', fj:'Fiji', pg:'Papua New Guinea',
    // Microstates / city-states (country slug often collides with capital — handled via "-city" suffix)
    mc:'Monaco', sm:'San Marino', va:'Vatican City', ad:'Andorra',
    li:'Liechtenstein', lu:'Luxembourg', mt:'Malta',
};

function makeCountrySlugSrv(cc) {
    const name = COUNTRY_NAMES_EN[cc];
    if (name) return name
        .normalize('NFD')                           // Côte → Co + combining circumflex
        .replace(/[\u0300-\u036f]/g, '')            // حذف العلامات التشكيليّة فقط
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-|-$/g, '');
    return cc;
}

// ===== Cache الـ sitemap (30 دقيقة TTL) =====
let _sitemapCache = { data: null, time: 0 };
const SITEMAP_TTL = 30 * 60 * 1000;
function invalidateSitemapCache() { _sitemapCache = { data: null, time: 0 }; }

// ===== Phase G — Curated slug redirects (db/curated-slugs.json) =====
// مولَّد عبر scripts/build-curated-sitemap.mjs من LOCAL_CITIES + LOCAL_PROVINCES
//   - يحتوي خريطة { oldSlug: canonicalSlug } (مثلًا mecca → makkah, giza-governorate → giza)
//   - يُحمَّل مرّة عند الإقلاع، ويُستخدم في 301 redirect handler قبل routing الرئيسيّ
let CURATED_REDIRECTS = {};
let CURATED_ENTRIES = [];
try {
    const _curatedPath = path.join(__dirname, 'db', 'curated-slugs.json');
    if (fs.existsSync(_curatedPath)) {
        const _curated = JSON.parse(fs.readFileSync(_curatedPath, 'utf8'));
        CURATED_REDIRECTS = _curated.redirects || {};
        CURATED_ENTRIES = _curated.entries || [];
        console.log(`[Curated] Loaded ${CURATED_ENTRIES.length} entries + ${Object.keys(CURATED_REDIRECTS).length} redirects`);
    }
} catch (e) {
    console.warn(`[Curated] Failed to load curated-slugs.json: ${e.message}`);
}

// ===== UAT-3b — Server-side i18n: load TRANSLATIONS from js/i18n.js =====
// Runs js/i18n.js inside a vm sandbox at boot. Stub document/window/etc so
// the DOM-touching helpers (setLanguage, etc.) don't throw — we only need
// the TRANSLATIONS object. Cached for the life of the process.
let TRANSLATIONS_BY_LANG = null;
try {
    const _i18nPath = path.join(__dirname, 'js', 'i18n.js');
    if (fs.existsSync(_i18nPath)) {
        const _vm = require('vm');
        const _i18nSrc = fs.readFileSync(_i18nPath, 'utf8');
        const _stubDoc = {
            documentElement: { lang: 'ar', dir: 'rtl', classList: { add: ()=>{}, remove: ()=>{}, contains: ()=>false, toggle: ()=>{} } },
            querySelectorAll: () => [],
            querySelector: () => null,
            getElementById: () => null,
            createElement: () => ({ setAttribute: ()=>{}, appendChild: ()=>{}, addEventListener: ()=>{} }),
            head: { appendChild: () => {} },
            body: { appendChild: () => {} },
            addEventListener: () => {},
            cookie: '',
            location: { pathname: '/', hostname: 'localhost', protocol: 'http:', href: 'http://localhost/' }
        };
        const _sandbox = {
            window: { location: _stubDoc.location, addEventListener: () => {}, removeEventListener: () => {} },
            document: _stubDoc,
            localStorage: { getItem: () => null, setItem: () => {}, removeItem: () => {} },
            navigator: { language: 'ar', languages: ['ar'] },
            console: { log: () => {}, warn: () => {}, error: () => {} },
            setTimeout: () => 0, clearTimeout: () => {}, setInterval: () => 0, clearInterval: () => {}
        };
        _sandbox.window.document = _stubDoc;
        _vm.createContext(_sandbox);
        // Append exposer line so const TRANSLATIONS becomes reachable on the sandbox
        _vm.runInContext(_i18nSrc + '\n;try{this.__TRANSLATIONS = TRANSLATIONS;}catch(e){}', _sandbox);
        TRANSLATIONS_BY_LANG = _sandbox.__TRANSLATIONS || null;
        if (TRANSLATIONS_BY_LANG) {
            const _langs = Object.keys(TRANSLATIONS_BY_LANG);
            const _arKeys = TRANSLATIONS_BY_LANG.ar ? Object.keys(TRANSLATIONS_BY_LANG.ar).length : 0;
            console.log(`[i18n] Loaded ${_langs.length} languages (${_langs.join(',')}) — ${_arKeys} keys per lang`);
        }
    }
} catch (e) {
    console.warn(`[i18n] Failed to load TRANSLATIONS: ${e.message}`);
    TRANSLATIONS_BY_LANG = null;
}

// HTML-escape attribute values (for placeholder/title/aria-label injection).
function _escAttr(s) {
    return String(s)
        .replace(/&/g, '&amp;')
        .replace(/"/g, '&quot;')
        .replace(/</g, '&lt;');
}

/**
 * UAT-3b — translate data-i18n attributes server-side.
 * Replaces inline Arabic default text/attribute values with the target-lang
 * value from TRANSLATIONS. Skipped for ar (default) and when dict missing.
 *
 * Handles 5 binding kinds:
 *   data-i18n               → replace text content of the host element
 *   data-i18n-placeholder   → replace `placeholder="..."` value
 *   data-i18n-title         → replace `title="..."` value
 *   data-i18n-aria-label    → replace `aria-label="..."` value
 *   data-i18n-alt           → replace `alt="..."` value (UAT-3c.2)
 *
 * Conservative: only swaps simple `<tag ...>TEXT</tag>` patterns where the
 * text content has no nested elements. Complex/nested cases fall back to the
 * existing client-side i18n.js handler (no regression).
 */
function _translateI18nAttrs(html, lang) {
    if (!lang || lang === 'ar' || !TRANSLATIONS_BY_LANG) return html;
    const dict = TRANSLATIONS_BY_LANG[lang];
    if (!dict) return html;
    // UAT-Z1: English fallback chain — when a key is missing from the
    // target lang dict (e.g. zakat.hero.title not yet translated to fr),
    // fall back to the English value before leaving the Arabic text in
    // place. Eliminates i18n-leakage for newly-added keys before all
    // 10 langs are translated. AR fallback never used for non-AR langs
    // (defeats the purpose).
    const enDict = TRANSLATIONS_BY_LANG.en || {};
    const _trans = (key) => {
        const t = dict[key];
        if (typeof t === 'string') return t;
        const e = enDict[key];
        if (typeof e === 'string') return e;
        return null;
    };

    // 1) text content for elements with data-i18n="key" (text-only body)
    html = html.replace(
        /<([a-z][a-z0-9-]*)\b([^>]*?\bdata-i18n=["']([^"']+)["'][^>]*?)>([^<]*)<\/\1>/gi,
        (m, tag, attrs, key, _text) => {
            const trans = _trans(key);
            if (trans === null) return m;
            return `<${tag}${attrs}>${trans}</${tag}>`;
        }
    );

    // 1a) UAT-SSR-FIX: mixed-content data-i18n — element has inline child
    //     markup (e.g. <svg>icon</svg>) followed by trailing text. The
    //     pattern at (1) requires a text-only body, so these slipped through
    //     and the Arabic label leaked into /en/ pages. Strategy: replace
    //     ONLY the trailing text after the last closing tag inside the
    //     body — preserves the inline icon, translates the visible label.
    html = html.replace(
        /<([a-z][a-z0-9-]*)\b([^>]*?\bdata-i18n=["']([^"']+)["'][^>]*?)>([\s\S]*?)<\/\1>/gi,
        (m, tag, attrs, key, body) => {
            // Skip if body has no nested tags (already handled by 1) or empty
            if (!/</.test(body)) return m;
            const trans = _trans(key);
            if (trans === null) return m;
            const lastClose = body.lastIndexOf('>');
            if (lastClose === -1) return m;
            const before  = body.slice(0, lastClose + 1);
            const trailRaw = body.slice(lastClose + 1);
            // Preserve any leading whitespace between icon and text
            const ws = (trailRaw.match(/^(\s+)/) || ['', ' '])[1] || ' ';
            return `<${tag}${attrs}>${before}${ws}${trans}</${tag}>`;
        }
    );

    // 1b) UAT-ICON-3: data-i18n-html — replaces the FULL inner HTML (allows
    //     translated content to contain markup like <li>...</li>).
    //     The matched element body can span multiple lines / contain nested
    //     elements, so use a non-greedy multiline match.
    html = html.replace(
        /<([a-z][a-z0-9-]*)\b([^>]*?\bdata-i18n-html=["']([^"']+)["'][^>]*?)>([\s\S]*?)<\/\1>/gi,
        (m, tag, attrs, key, _body) => {
            const trans = _trans(key);
            if (trans === null) return m;
            return `<${tag}${attrs}>${trans}</${tag}>`;
        }
    );

    // 2) attribute-bound i18n: placeholder / title / aria-label / alt
    const attrPairs = [
        ['data-i18n-placeholder', 'placeholder'],
        ['data-i18n-title',       'title'],
        ['data-i18n-aria-label',  'aria-label'],
        ['data-i18n-alt',         'alt'],
    ];
    for (const [keyAttr, valAttr] of attrPairs) {
        const tagRe = /<[a-z][a-z0-9-]*\b[^>]*?\/?>/gi;
        const valRe = new RegExp(`(^|<[a-z][a-z0-9-]*|\\s)(${valAttr}=["'][^"']*["'])`, 'i');
        const keyRe = new RegExp(`(?:^|\\s)${keyAttr}=["']([^"']+)["']`, 'i');
        html = html.replace(tagRe, tagStr => {
            const km = tagStr.match(keyRe);
            if (!km) return tagStr;
            const trans = _trans(km[1]);
            if (trans === null) return tagStr;
            const escaped = _escAttr(trans);
            if (valRe.test(tagStr)) {
                return tagStr.replace(valRe, `$1${valAttr}="${escaped}"`);
            }
            return tagStr.replace(/(\/?>)\s*$/, ` ${valAttr}="${escaped}"$1`);
        });
    }
    return html;
}

function makeCitySlugSrv(nameEn, lat, lng) {
    // NFD decomposes accented chars (ã → a+◌̃, ü → u+◌̈, ç → c+◌̧)
    // ثمّ نحذف العلامات التشكيليّة [U+0300..U+036F] فقط، فيتبقّى الحرف الأساسيّ ASCII
    const latin = (nameEn || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9\s]+/g, '')
        .trim()
        .replace(/\s+/g, '-');
    if (latin.length >= 2) return latin;
    const la = Math.abs(lat).toFixed(1) + (lat >= 0 ? 'n' : 's');
    const lo = Math.abs(lng).toFixed(1) + (lng >= 0 ? 'e' : 'w');
    return `${la}-${lo}`;
}

// ===== Round 10: Legacy slug — الصيغة القديمة (بلا NFD) لتوافُق رجعيّ =====
// كان يُحوِّل مثلاً: "São Paulo" → "so-paulo" (مُشوَّه بسبب حذف ã كاملاً).
// نُعيد استعماله في _getCitySlugIndex لِيُسجَّل المدينة تحت كلّ من الـ slug الجديد والقديم،
// فلا تُعطب الروابط المُفهرَسة/المحفوظة مسبقاً. يُستخدم فقط عند الـ lookup — لا يُصدَر في sitemap.
function _makeCityLegacySlug(nameEn) {
    const latin = (nameEn || '').toLowerCase().replace(/[^a-z0-9\s]+/g, '').trim().replace(/\s+/g, '-');
    return latin.length >= 2 ? latin : null;
}

