                        if (legacySlug && legacySlug !== slug && !_CITY_SLUG_INDEX[legacySlug]) {
                            _CITY_SLUG_INDEX[legacySlug] = { nameAr: c.nameAr, nameEn: c.nameEn, lat: c.lat, lng: c.lng, cc };
                        }
