    const _HY_SFX_CITY = { ar:' هـ', en:' AH', fr:' H', tr:' H', ur:'ھ', de:' AH', id:' H', es:' H', bn:' হিজরি', ms:' H' };
    const _gDayNum = _gNow.getUTCDate();
