            const tiered = [
                f.withPrayer,
                f.titleLong,
                f.countdown,
                f.adhan,
                f.titleAlt,
                f.timeLeft,
            ].filter(Boolean);
            // 1) First candidate landing in [50, 60].
            for (const t of tiered) {
                if (len(t) >= 50 && len(t) <= 60) return t;
            }
            // 2) Longest candidate ≤ 60.
            const ok = tiered.filter(t => len(t) <= 60).sort((a, b) => len(b) - len(a));
